<?php
namespace App\Http\Controllers\Admin; use App\Domain\CaseStudies\CaseStudyCache; use App\Http\Controllers\Controller; use App\Models\{CaseStudy,CaseStudyHighlight,CaseStudyMetric}; use Illuminate\Http\{RedirectResponse,Request}; use Illuminate\Validation\ValidationException; class CaseStudyChildController extends Controller { public function store(Request $request,CaseStudy $caseStudy,string $type):RedirectResponse{$isMetric=$type==='metrics';$limit=$isMetric?8:12;$relation=$isMetric?'metrics':'highlights';if($caseStudy->{$relation}()->count()>=$limit){throw ValidationException::withMessages([$type=>"A maximum of {$limit} {$type} is allowed."]);}$rules=$isMetric?['label'=>['required','string','max:160'],'value'=>['required','string','max:160'],'prefix'=>['nullable','string','max:30'],'suffix'=>['nullable','string','max:30'],'description'=>['nullable','string','max:2000']]:['title'=>['required','string','max:160'],'description'=>['required','string','max:4000'],'icon'=>['nullable','string','max:40','regex:/^[a-z0-9-]+$/']];$data=$request->validate($rules);$data['display_order']=(int)$caseStudy->{$relation}()->max('display_order')+1;$data['is_active']=true;$caseStudy->{$relation}()->create($data);CaseStudyCache::forget($caseStudy->id);return back();} public function destroy(CaseStudy $caseStudy,string $type,int $child):RedirectResponse{$model=$type==='metrics'?CaseStudyMetric::class:CaseStudyHighlight::class;$item=$model::where('case_study_id',$caseStudy->id)->findOrFail($child);$item->delete();CaseStudyCache::forget($caseStudy->id);return back();} }
